def drums_bar(T, r0, style="A", fill=None, crash=False, open_hats=(14,), ghost=False):
    if crash:
        T.set(r0, SNARE, note=nn("C4"), inst=I_CRASH, vol=V(52))
    if style == "A":
        kicks = [0, 4, 8, 12]
    elif style == "B":
        kicks = [0, 4, 8, 11, 12]
    elif style == "half":
        kicks = [0, 8]
    elif style == "none":
        kicks = []
    else:
        kicks = [0, 4, 8, 12]
    if fill == "roll8":
        kicks = [k for k in kicks if k < 8] + [8]
    for k in kicks:
        T.set(r0 + k, KICK, note=nn("C4"), inst=I_KICK, vol=V(64 if k % 8 == 0 else 56))
    if style in ("A", "B"):
        for s in (4, 12):
            if fill == "roll8" and s == 12:
                continue
            T.set(r0 + s, SNARE, note=nn("C4"), inst=I_SNARE, vol=V(64))
        if ghost:
            T.set(r0 + 10, SNARE, note=nn("C4"), inst=I_SNARE, vol=V(20))
    if fill == "roll8":
        vols = [26, 30, 34, 40, 46, 52, 58, 64]
        for i, v in enumerate(vols):
            T.set(r0 + 8 + i, SNARE, note=nn("C4"), inst=I_SNARE, vol=V(v))
        T.set(r0 + 13, KICK, note=nn("C4"), inst=I_TOM, vol=V(60))
        T.set(r0 + 15, KICK, note=nn("A3"), inst=I_TOM, vol=V(60))
    elif fill == "roll4":
        for i, v in enumerate([40, 48, 56, 64]):
            T.set(r0 + 12 + i, SNARE, note=nn("C4"), inst=I_SNARE, vol=V(v))
    elif fill == "clap":
        T.set(r0 + 14, SNARE, note=nn("C4"), inst=I_CLAP, vol=V(50))
    if style != "none":
        hv = [50, 24, 36, 24]
        for i in range(16):
            if i in open_hats:
