                  vol=V(gl[i] * gain), eff=0, par=par)
    if right:
        b2 = base + (3 if minor else 4)
        par = 0x49 if minor else 0x38
        for i in range(16):
            T.set(r0 + i, ARPR, note=b2 if i in (0, 8) else 0, inst=I_ARPT if i in (0, 8) else 0,
                  vol=V(gr[i] * gain), eff=0, par=par)


